 await page.locator('[data-view="archive"]').click();
 const downloadPromise=page.waitForEvent('download');
 await page.locator('[data-action="download-genome"]').click();
 const download=await downloadPromise;
 const downloadName=download.suggestedFilename();
 await page.locator('[data-action="use-genome"]').click();
 const seeded=await page.locator('#view-root').innerText();
 if(!seeded.includes('Living system')) throw new Error('archive seed action did not return to a new world');
 if(errors.length) throw new Error(`browser errors: ${errors.join('; ')}`);
 console.log(JSON.stringify({initialPlateCells:initial,selectedCell:selected,archivedCellsAdded:archivedCount,selectedArchiveCell:selectedArchive,inspectionHeading:inspected,downloadName,seedWorldAction:'passed',screenshot:'genesis-latest.jpeg',browserErrors:errors},null,2));
 await context.close();
} finally { await browser.close(); }
