const fs = require('fs');
async function main() {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const target = targets.find(x => x.type === 'page');
  if (!target) throw new Error('No Chrome page target');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = e => {
    const msg = JSON.parse(e.data);
    if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); msg.error ? p.reject(new Error(msg.error.message)) : p.resolve(msg.result); }
  };
  const send = (method, params={}) => new Promise((resolve,reject) => { const n=++id; pending.set(n,{resolve,reject}); ws.send(JSON.stringify({id:n,method,params})); });
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height:1900,deviceScaleFactor:1,mobile:false});
  await send('Page.navigate',{url:'http://127.0.0.1:8765/'});
  await send('Runtime.evaluate',{expression:'new Promise(r => { if (document.readyState === "complete") r(); else addEventListener("load",r,{once:true}); })',awaitPromise:true});
  const result = await send('Runtime.evaluate',{expression:'new Promise(async resolve => { await document.fonts.ready; document.querySelector(".nav-item[data-view=cell]").click(); requestAnimationFrame(() => requestAnimationFrame(() => resolve({title:document.querySelector("#breadcrumb-current").textContent,readings:document.querySelectorAll(".cell-reading").length,summary:document.querySelector(".plate-summary").innerText,errors:document.querySelector("#view-root").innerText.includes("undefined")}))); })',awaitPromise:true,returnByValue:true});
  console.log('Browser verification:',JSON.stringify(result.result.value));
  const metrics = await send('Page.getLayoutMetrics');
  const height = Math.min(2800, Math.ceil(metrics.cssContentSize.height));
  await send('Emulation.setDeviceMetricsOverride',{width:1440,height,deviceScaleFactor:1,mobile:false});
  const shot = await send('Page.captureScreenshot',{format:'jpeg',quality:88,fromSurface:true,captureBeyondViewport:true});
  fs.writeFileSync('/tmp/opencode/genesis-latest.jpeg',Buffer.from(shot.data,'base64'));
  ws.close();
}
main().catch(e=>{console.error(e);process.exit(1)});
