90: case'Whole-genome sequencing':S.samples.dna=true;values=[['Read coverage',`${(18+rng.next()*22).toFixed(1)}×`],['Assembly length',`${seq.length.toLocaleString()} bp`],['Variant calls',`${S.genome.mutations} inherited`]];note=`Reference assembly computed directly from this genome. Coverage and error are simulated; no raw reads or real instrument model are generated.`;break;

91: case'Gene expression assay':values=[['Target',gene.name],['Relative expression',`${f(traitMap(S.genome,S.env)[gene.name],3)}×`],['Replicate CV',`${(err*100*2).toFixed(1)}%`]];note=`Expression is calculated from ${gene.regulation} promoter response, current environmental conditions and epigenetic state. Variation is an assay-noise estimate.`;break;

92: case'Protein analysis':values=[['Predicted peptide',translate(transcribe(gene))],['Length',`${translate(transcribe(gene)).length} aa`],['Relative abundance',`${f(traitMap(S.genome,S.env)[gene.name],2)}×`]];note=`In-silico translation of ${gene.id}; protein abundance follows modeled transcription. Folding, post-translational modifications, and proteomics spectra are not simulated.`;break;

93: case'Cell viability':values=[['Estimated viable',`${f(S.viability,1)}%`],['Cells counted',`${S.cellCount.toLocaleString()}`],['95% CI',`±${f(1.96*Math.sqrt(S.viability*(100-S.viability)/Math.max(1,S.cellCount)),1)} pp`]];note='Binomial confidence interval assumes independent, representative sampled cells. Model state is correlated, so interval is likely optimistic.';break;

94: case'Karyotype':values=[['Chromosome count',`${S.genome.chromosomes} pairs (model)`],['Aneuploidy detected','None modeled'],['Confidence','Low · schematic']];note='Chromosome count is generated at world creation. Structural rearrangements and cell-to-cell karyotype variation are not represented.';break;

95: case'CRISPR edit simulation':values=[['Target locus',gene.id],['Edit outcome','In-silico substitution'],['Predicted phenotype',gene.name]];note=`A single coding-base change is modeled in ${gene.id}. Off-target edits, repair pathways, mosaicism, delivery, and biological safety are outside this educational simulation.`;gene.coding=gene.coding.slice(0,3)+({A:'G',T:'C',C:'A',G:'T'}[gene.coding[3]])+gene.coding.slice(4);gene.mutation={from:'simulated',position:3};gene.activity=clamp(gene.activity*.96,.05,1);S.genome.mutations++;S.genome.sequence=genomeSequence(S.genome);S.damage=clamp(S.damage+.4,0,100);break;

96: case'Comparative genomics':{let ref=(S.archive||[]).find(x=>x.id!==S.genome.id);let sim=ref?sequenceSimilarity(seq,ref.sequence):1;values=[['Reference',ref?.id||'No archived reference'],['Sequence identity',`${f(sim*100,2)}%`],['Length difference',`${ref?seq.length-ref.sequence.length:0} bp`]];note=ref?'Identity is an aligned-position similarity proxy (not a full alignment); reference selected from the first archived genome.':'Archive a second genome to enable between-lineage comparisons.';break}}

97: S.experimentCount++;let result={id:`EXP-${String(S.experimentCount).padStart(3,'0')}`,date:new Date().toLocaleString(),protocol:p,genome:S.genome.id,values,note};S.labResults.unshift(result);S.events.unshift({tick:S.tick,type:'lab',text:`${p} completed on ${S.genome.id}; ${values[0][1]} recorded.`});addNotebook(`${p} · ${result.id}`,note,p);let progress=recordResearchSuccess(p);storeState();render();toast(`${researchSuccessToast(p,progress)} · ${result.id}`)}

98: function sequenceSimilarity(a,b){if(!b)return 1;let n=Math.min(a.length,b.length),same=0;for(let i=0;i<n;i++)if(a[i]===b[i])same++;return same/Math.max(a.length,b.length)}

99: function doSequence(){if(!S.samples.dna){toast('Collect a sample and extract DNA before sequencing.');currentView='lab';activeProtocol='DNA extraction';render();return}S.genome.sequence=genomeSequence(S.genome);S.samples.sequenced=true;let bases=S.genome.sequence.length;S.events.unshift({tick:S.tick,type:'lab',text:`Sequence assembly completed for ${S.genome.id}; ${bases.toLocaleString()} bp in the simulated reference.`});addNotebook('Genome sequencing completed',`Assembled ${bases.toLocaleString()} bp with GC content ${f(gc(S.genome.sequence),2)}%. ${S.genome.genes.length} model genes annotated.`, 'SEQUENCING');let progress=recordResearchSuccess('Genome sequencing');storeState();render();toast(`${bases.toLocaleString()} bp assembled · ${researchSuccessToast('Genome sequencing',progress)}`)}

100: function download(name,data,type='application/json'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

101: function handleAction(action){let a=typeof action==='string'?action:action.dataset.action;switch(a){case'toggle':S.playing=!S.playing;storeState();render();toast(S.playing?'Simulation resumed.':'Simulation paused.');break;case'sample':sample();break;case'sequence':doSequence();break;case'save-genome':saveGenome();break;case'run-lab':runLab();break;case'evolve':S.playing=false;for(let i=0;i<10;i++){S.tick+=25;generationStep()}storeState();render();toast('Ten generations simulated with inherited variation.');break;case'plate-live':{let added=addCellsToPlate(S.genome,false,6);render();if(added.length)toast(`${added.length} live cells added to the observatory plate.`);break}case'plate-archive':{let value=$('#plate-archive')?.value,index=Number(value),genome=value!==''?S.archive?.[index]:null;if(!Number.isInteger(index)||!genome){toast('Choose an archived genome first.');return}let added=addCellsToPlate(genome,true,6);render();if(added.length)toast(`${added.length} cells from ${genome.id} added to the plate.`);break}case'inspect-genome':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell)return;S.inspectedGenome=JSON.parse(JSON.stringify(plateGenome(cell)));S.selectedGene=0;currentView='genome';render();break}case'clear-inspection':delete S.inspectedGenome;S.selectedGene=0;render();break;case'cell-cycle':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell){toast('Select a cell first.');break}cell.atp=clamp(cell.atp-.12,.2,7);cell.cycleProgress=1;let checkpoint=cycleCheckpoint(cell),divided=checkpoint==='PASS'&&dividePlateCell(cell);let outcome=divided?'passed checkpoint and divided':checkpoint!=='PASS'?`held at checkpoint: ${checkpoint}`:'passed checkpoint; division capped by plate capacity';S.events.unshift({tick:S.tick,type:'lab',text:`${cell.id} ${outcome}.`});addNotebook('Cell cycle checkpoint',`${cell.id} ${outcome}. ATP proxy ${f(cell.atp,2)} mmol/L; division count ${cell.divisions||0}.`,'CELL CYCLE');storeState();render();toast(divided?'Checkpoint passed; daughter cell added to the plate.':checkpoint!=='PASS'?`Division paused by checkpoint: ${checkpoint}.`:'Checkpoint passed; plate is full, so division is capped.');break}case'stain':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell){toast('Select a cell first.');break}cell.stained=true;cell.stainIntensity=clamp(cell.viability*.7+cell.membrane*.3,0,100);S.events.unshift({tick:S.tick,type:'lab',text:`Fluorescent viability stain applied to ${cell.id}.`});addNotebook('Fluorescent stain applied',`${cell.id} stained; fluorescence intensity proxy ${f(cell.stainIntensity,1)}% combines viability and membrane integrity.`,'STAINING');storeState();render();toast('Selected cell stained; fluorescence reflects viability and membrane integrity.');break}case'remove-cell':{if(S.plate.length<=1){toast('Keep at least one cell on the observatory plate.');break}let index=S.plate.findIndex(c=>c.id===S.selectedCellId);if(index<0)break;let [removed]=S.plate.splice(index,1);S.selectedCellId=S.plate[Math.min(index,S.plate.length-1)].id;storeState();render();toast(`${removed.id} removed from the plate.`);break}case'add-note':$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>Add field note</h2><button class="modal-close" data-action="close-modal">×</button></div><label>Observation title</label><input id="note-title" placeholder="e.g. Increased stress response" maxlength="90"><label>Notes / hypothesis</label><textarea id="note-body" placeholder="Record an observation, hypothesis, or next step…"></textarea><div class="modal-footer"><button class="subtle-button" data-action="close-modal">Cancel</button><button class="action-button primary" data-action="save-note">Save to notebook</button></div></div></div>`;break;case'save-note':{let title=$('#note-title')?.value.trim(),text=$('#note-body')?.value.trim();if(!title||!text){toast('Add a title and observation first.');return}addNotebook(title,text);$('#modal-root').innerHTML='';currentView='notebook';render();toast('Field note saved.');break}case'export':download('genesis-database.json',JSON.stringify({format:'genesis-genome-archive-v1',archive:S.archive||[],notebook:S.notebook||[]},null,2));break;case'import':$('#import-file').click();break;case'download-genome':{let g=S.archive[Number(action.dataset.index)];if(g)download(`${g.id}.json`,JSON.stringify(g,null,2));break}case'use-genome':{let g=S.archive[Number(action.dataset.index)];if(g)newWorld(g);break}case'close-modal':$('#modal-root').innerHTML='';break;case'reset-world':$('#modal-root').innerHTML='';newWorld();break}}

102: document.addEventListener('click',e=>{let nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;render();return}let plateCell=e.target.closest('[data-plate-cell]');if(plateCell){S.selectedCellId=plateCell.dataset.plateCell;storeState();render();return}let action=e.target.closest('[data-action]');if(action){handleAction(action);return}let p=e.target.closest('[data-protocol]');if(p){activeProtocol=p.dataset.protocol;render();return}let sp=e.target.closest('[data-speed]');if(sp){S.speed=Number(sp.dataset.speed);storeState();render();return}let gene=e.target.closest('[data-gene]');if(gene){S.selectedGene=Number(gene.dataset.gene);render();return}if(e.target.closest('#new-world')){newWorld();return}if(e.target.closest('#settings-btn')){$('#modal-root').innerHTML=settingsModal();return}if(e.target.closest('#seed-button')){navigator.clipboard?.writeText(String(S.seed));toast('World seed copied.');return}if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''});

